Chapter: Nine days

The paragraph: In June the share price fell from 104.5 euros to 1.28 euros. Nobody could stop it.

This graphic covers: The share price fell from 104.5 euros to 1.28 euros.
Length: 7.0 s

Words spoken in it, from its start:
0.2 s  Banks
0.7 s  held
1.2 s  60%,
1.7 s  funds
2.2 s  30%,
2.7 s  and
3.2 s  the
3.7 s  public
4.2 s  10%.

Intent: Banks held 60%, funds 30%, the public 10%.
Rests on claims: 4

A passing design of this technique (progress-bars: labelled bars filling to their share on equal tracks, one after another, the largest share on the hero spring), in this sandbox and on the tokens, for its mechanics, its timing and its standard. It uses: draw on, tally. Its concept came from its own narration: find this slot's own rather than reusing its layout. Its words and figures are its own; yours come from this slot and its claims:
````jsx
// Concept: one hundred per cent, shared out. Every holder gets the same empty track, the
// whole, before anything is said, and each one's share fills in as it is spoken, so the
// reading is the difference in how far each track fills.
// Storyboard, on the narration's clock:
//   0.0 s  the hook: the three empty tracks fade in, one stagger step apart
//   0.2 s  "Banks": the name rises in; 1.2 s "60%": its bar fills while the figure counts
//          with it, landing on the claim's value, the largest share on the hero spring
//   1.7 s  "funds" and 2.2 s "30%": the same for the second row
//   3.2 s  "the public" and 4.2 s "10%": the same for the third
//   to the end: the rows hold while the camera keeps a slow push
const ROWS = [
  { label: 'Banks', named: 'Banks', share: 60, said: '60%' },
  { label: 'Funds', named: 'funds', share: 30, said: '30%' },
  { label: 'The public', named: 'the', share: 10, said: '10%' },
]

// When a word is spoken, at or after a time, or a fallback when it is not.
function spokenAt(text, afterMs, fallbackMs, words) {
  const said = words.find((word) => word.atMs >= afterMs && word.text.indexOf(text) === 0)
  return said ? said.atMs : fallbackMs
}

// Helpers, called directly: 0 to 1 over lengthMs from atMs, held at 1, one per curve,
// since each interpolate names its curve in the call.
function range(fps, atMs, lengthMs) {
  return [motion.frames(atMs, fps), motion.frames(atMs + lengthMs, fps)]
}
function arrive(frame, fps, atMs, lengthMs) {
  return Remotion.interpolate(frame, range(fps, atMs, lengthMs), [0, 1], {
    easing: motion.ease.enter, extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
  })
}
function travel(frame, fps, atMs, lengthMs) {
  return Remotion.interpolate(frame, range(fps, atMs, lengthMs), [0, 1], {
    easing: motion.ease.move, extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
  })
}
function tally(frame, fps, atMs, lengthMs) {
  return Remotion.interpolate(frame, range(fps, atMs, lengthMs), [0, 1], {
    easing: motion.ease.linear, extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
  })
}

// The fade with rise, for the names.
function rise(amount, unit) {
  return { opacity: amount, transform: 'translateY(' + (1 - amount) * motion.px.rise * unit + 'px)' }
}

// One holder: its name, its figure counting as the bar fills, and the bar on its track.
function row(frame, fps, spec) {
  const { colors, fonts } = spec.brand
  const unit = spec.unit
  const named = arrive(frame, fps, spec.namedAt, motion.ms.enter)
  const tracked = arrive(frame - motion.stagger(spec.index, fps), fps, 0, motion.ms.enter)
  // A fill is progress, so it runs on the linear curve over motion.ms.draw, figure and bar together.
  const fill = tally(frame, fps, spec.fillAt, motion.ms.draw)
  // The largest share's figure lands on the beat's one hero spring; the others scale in from
  // motion.scale.enter on the arrival curve.
  const landed = spec.hero
    ? Remotion.spring({ frame, fps, delay: motion.frames(spec.fillAt, fps), config: motion.spring.hero })
    : arrive(frame, fps, spec.fillAt, motion.ms.enter)
  const scale = motion.scale.enter + (1 - motion.scale.enter) * landed
  const started = frame >= motion.frames(spec.fillAt, fps)
  return (
    <div key={spec.row.label} style={{ display: 'flex', flexDirection: 'column', gap: 16 * unit }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}>
        <div style={{ fontFamily: fonts.title, fontSize: 60 * unit, color: colors.textPrimary, ...rise(named, unit) }}>
          {spec.row.label}
        </div>
        <div style={{ fontFamily: fonts.numbers, fontSize: 96 * unit, lineHeight: 1, color: spec.color, transform: 'scale(' + scale + ')', transformOrigin: 'right bottom' }}>
          {started ? Math.round(spec.row.share * fill) + '%' : ''}
        </div>
      </div>
      <div style={{ height: 40 * unit, borderRadius: 20 * unit, backgroundColor: Remotion.withAlpha(colors.textSecondary, 0.16), opacity: tracked }}>
        <div style={{ width: spec.row.share * fill + '%', height: '100%', borderRadius: 20 * unit, backgroundColor: spec.color }} />
      </div>
    </div>
  )
}

function Graphic(props) {
  const frame = Remotion.useCurrentFrame()
  const { width, height, fps } = Remotion.useVideoConfig()
  const { colors } = props.brand
  const inset = props.safeArea
  const portrait = height > width
  const unit = Math.min(width, height) / 1080
  // Each row's two times, read in order so "the" finds the one before "public", not an earlier one.
  let cursor = 0
  const times = ROWS.map((item, index) => {
    const namedAt = spokenAt(item.named, cursor, motion.ms.enter + index * motion.ms.count, props.words)
    const fillAt = spokenAt(item.said, namedAt, namedAt + motion.ms.enter, props.words)
    cursor = fillAt
    return { namedAt, fillAt }
  })
  const largest = Math.max(...ROWS.map((item) => item.share))
  const push = travel(frame, fps, 0, props.durationMs)

  return (
    <Remotion.AbsoluteFill
      style={{
        paddingTop: inset.top, paddingRight: inset.right,
        paddingBottom: inset.bottom, paddingLeft: inset.left,
        justifyContent: 'center', alignItems: 'center',
        transform: 'scale(' + (1 + 0.03 * push) + ')',
      }}
    >
      <div style={{ width: portrait ? '100%' : '76%', display: 'flex', flexDirection: 'column', gap: (portrait ? 110 : 60) * unit }}>
        {ROWS.map((item, index) =>
          row(frame, fps, {
            brand: props.brand, unit, row: item, namedAt: times[index].namedAt, fillAt: times[index].fillAt,
            index, color: colors.chartSeries[index % colors.chartSeries.length], hero: item.share === largest,
          }),
        )}
      </div>
    </Remotion.AbsoluteFill>
  )
}

````
